pub fn normalise(s: &str) -> String {
    let straight: String = s
        .chars()
        .map(|c| match c {
            '‘' | '’' | '‚' | '‛' => '
            '“' | '”' | '„' | '‟' => "",
            c => c,
        })
        .collect();
    straight.split_whitespace().collect::<Vec<_>>().join(" ")
}

